ntries'=>'Salli vain kirjautuneiden käyttäjien nähdä kaikki merkinnät','Allow logged in users to edit form entries'=>'Salli kirjautuneiden käyttäjien muokata lomakkeen merkintöjä','Allow to Configure Global Validation Message'=>'Salli globaalin vahvistusviestin määrittäminen','How to add Custom CSS/JS'=>'Kuinka lisätä mukautettu CSS/JS']];